// Rabbit avatar levels: reaching `count` learned characters unlocks the avatar.
// The art lives in public/avatars/, generated by scripts/build-avatars.js.
export const LEVELS = [
  { count: 0, name: '小灰兔' },
  { count: 5, name: '发芽兔' },
  { count: 10, name: '蝴蝶结兔' },
  { count: 20, name: '围巾兔' },
  { count: 30, name: '小花兔' },
  { count: 45, name: '眼镜兔' },
  { count: 60, name: '小画家兔' },
  { count: 80, name: '音乐兔' },
  { count: 100, name: '小厨师兔' },
  { count: 130, name: '小警长兔' },
  { count: 160, name: '魔法兔' },
  { count: 200, name: '小船长兔' },
  { count: 250, name: '小博士兔' },
  { count: 300, name: '花仙兔' },
  { count: 360, name: '星星兔' },
  { count: 420, name: '天使兔' },
  { count: 500, name: '王子兔' },
  { count: 600, name: '国王兔' },
  { count: 700, name: '彩虹兔' },
  { count: 800, name: '金兔大王' },
]

LEVELS.forEach((l, i) => {
  l.level = i + 1
  l.avatar = `/avatars/rabbit-${String(i + 1).padStart(2, '0')}.svg`
})

export const levelFor = (count) => LEVELS.findLast((l) => count >= l.count)
